        if name in directives:
            return directives[name].strip()
    return None


def build_delimited(depot, seq, rows):
    result = []
    decimal_comma = depot == "west"
    for fields, header, directives in rows:
        extra = None
        if len(fields) > len(header):
            extra = fields[len(header):]
            fields = fields[:len(header)]
        elif len(fields) < len(header):
            fields = fields + [""] * (len(header) - len(fields))
        row = dict(zip(header, fields))
        row_unit = None
        if extra:
            for item in extra:
                unit = clean_unit(item)
                if unit in FACTORS:
                    row_unit = unit
        if depot == "east":
            rtype, rid, shipped, weight, status = row["type"], row["id"], row["shipped"], row["gross"], row["status"]
        elif depot == "lakeside":
            rtype, rid, shipped, weight, status = row["kind"], row["id"], row["shipped"], row["gross_kg"], row["status"]
        elif depot == "harbor":
            rtype, rid, shipped, weight, status = row["rec"], row["ref"], row["date"], row["weight"], row["state"]
        elif depot == "river":
            rtype, rid, shipped, weight, status = row["t"], row["ref"], row["shipped"], row["weight"], row["status"]
        else:
            rtype, rid, shipped, weight, status = row["typ"], row["id"], row["shipped"], row["weight"], row["status"]
        rtype = TYPE_MAP[rtype.strip().lower()]
        number = sh_number(rid)
        if rtype == "void":
            result.append((rtype, number, None))
            continue
        number_text, unit = split_value_unit(weight)
        if unit is None and depot == "lakeside":
            unit = "kg"
        if unit is None:
            unit = row_unit
        if unit is None:
            unit = unit_directive(directives)
        if unit is None:
            unit = "kg"
        if depot == "harbor":
            status = {"dlv": "delivered", "dll": "delivered_late"}.get(status.strip().lower(), status)
        kg = parse_number(number_text, decimal_comma) * FACTORS[unit]
        form = date_directive(directives) or BASE_DATE[depot]
        if depot == "west":
            form = "dd.mm.yyyy"
        month = month_of_date(parse_date(shipped, form))
        result.append((rtype, number, (counted(norm_status(status)), kg, month)))
    return result


def parse_fixed(text):
    layouts = {
        "FW1": (42, lambda l: (l[9], l[0:9], l[10:17], l[17:25], l[25], "yyyyddd", "g")),
        "FW2": (43, lambda l: (l[0], l[1:10], l[10:18], l[18:26], l[26], "yyyymmdd", "cg")),
        "FW3": (41, lambda l: (l[16], l[0:9], l[9:16], l[17:24], l[24], "yyyyddd", "dlb")),
    }
    by_length = {spec[0]: name for name, spec in layouts.items()}
    current = None
    seq = None
    out = []
    for line in split_lines(text):
        line = line.replace("\x0c", "")
        if line.startswith("#"):
            match = re.match(r"#LAYOUT\s+(\w+)", line)
            if match:
                current = match.group(1).upper()
            match = re.match(r"#SEQ\s+(\d+)", line)
            if match:
                seq = int(match.group(1))
            continue
        if not line.strip() or "SHIPMENT LISTING" in line:
            continue
        name = by_length.get(len(line))
        if name is None:
            name = by_length.get(len(line.rstrip("\n")))
        if name is None:
            if current is None:
                continue
            name = current
            line = line.ljust(layouts[name][0])[:layouts[name][0]]
        rtype, rid, shipped, weight, status, dform, wunit = layouts[name][1](line)
        rtype = TYPE_MAP[rtype.strip().lower()]
        number = sh_number(rid)
        if rtype == "void":
            out.append((rtype, number, None))
            continue
        value = Decimal(int(weight))
        if wunit == "g":
            kg = value * FACTORS["g"]
        elif wunit == "cg":
            kg = value / 100
        else:
            kg = value / 10 * FACTORS["lb"]
        shipped = shipped.strip()
        if dform == "yyyyddd":
            day = date(int(shipped[:4]), 1, 1) + timedelta(days=int(shipped[4:7]) - 1)
        else:
            day = date(int(shipped[:4]), int(shipped[4:6]), int(shipped[6:8]))
        code = status.strip().upper()
        out.append((rtype, number, (code in ("D", "L"), kg, month_of_date(day))))
    return seq, out


def parse_north(text):
    seq = None
    out = []
    for line in split_lines(text):
        if not line.strip():
            continue
        value = json.loads(line)
        items = value if isinstance(value, list) else [value]
        for item in items:
            if "meta" in item and isinstance(item["meta"], dict):
                if "seq" in item["meta"]:
                    seq = int(item["meta"]["seq"])
                continue
            rtype = TYPE_MAP[str(item.get("kind", "new")).strip().lower()]
            number = sh_number(str(item["id"]))
            if rtype == "void":
                out.append((rtype, number, None))
                continue
            kg = None
            for key, val in item.items():
                if key.startswith("weight_") and clean_unit(key[7:]) in FACTORS:
                    kg = Decimal(str(val)) * FACTORS[clean_unit(key[7:])]
            month = parse_iso_time(item["shipped_at"])
            out.append((rtype, number, (counted(norm_status(item["status"])), kg, month)))
    return seq, out


def parse_central(text):
    root = ET.fromstring(text.encode("utf-8") if not text.startswith("<?xml") else
                         re.sub(r"^<\?xml[^>]*\?>", "", text).encode("utf-8"))
    seq = int(root.get("seq")) if root.get("seq") is not None else None
    root_unit = clean_unit(root.get("weight-unit", "kg"))
    out = []
    for element in root.iter("shipment"):
        rtype = TYPE_MAP[(element.get("type") or "new").strip().lower()]
        number = sh_number(element.get("id", ""))
        if rtype == "void":
            out.append((rtype, number, None))
            continue
        weight = element.find("weight")
        unit = clean_unit(weight.get("unit")) if weight.get("unit") else root_unit
        kg = Decimal(weight.text.strip().replace(",", "")) * FACTORS[unit]
        shipped_child = element.find("shipped")
        if shipped_child is not None:
            month = parse_iso_time(shipped_child.text)
        else:
            raw = element.get("shipped").strip()
            day, mon, year = raw.split()
            month = "%04d-%02d" % (int(year), MONTHS[mon[:3].lower()])
        status = element.find("status").text
        out.append((rtype, number, (counted(norm_status(status)), kg, month)))
    return seq, out


def load_export(depot, path):
    text = read_text(path)
    if depot == "central":
        return parse_central(text)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_fixed(text)
    seq, rows = parse_delimited(depot, text)
    return seq, build_delimited(depot, seq, rows)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        seq, records = load_export(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else 0, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, items in exports.items():
        state = {}
        for seq, name, records in sorted(items, key=lambda item: (item[0], item[1])):
            for rtype, number, info in records:
                if rtype == "new":
                    if number in state:
                        resends += 1
                    else:
                        state[number] = info
                elif rtype == "correction":
                    state[number] = info
                    corrections += 1
                else:
                    state.pop(number, None)
                    corrections += 1
        current[depot] = state

    depots = {depot: {"shipments": 0, "total": Decimal(0)} for depot in sorted(exports)}
    months = {}
    owners = {}
    handovers = 0
    for depot in sorted(current, key=lambda d: ORDER.index(d) if d in ORDER else len(ORDER)):
        for number, info in current[depot].items():
            if number in owners:
                continue
            owners[number] = depot
    seen = {}
    for depot, state in current.items():
        for number in state:
            seen[number] = seen.get(number, 0) + 1
    handovers = sum(1 for count in seen.values() if count > 1)
    for number, depot in owners.items():
        is_counted, kg, month = current[depot][number]
        if not is_counted:
            continue
        depots[depot]["shipments"] += 1
        depots[depot]["total"] += kg
        entry = months.setdefault(month, {"shipments": 0, "total": Decimal(0)})
        entry["shipments"] += 1
        entry["total"] += kg

    def fmt(entry):
        return {"shipments": entry["shipments"], "total_kg": float(round(entry["total"], 2))}

    summary = {
        "depots": {depot: fmt(depots[depot]) for depot in sorted(depots)},
        "months": {month: fmt(months[month]) for month in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(summary, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main()
